/* press-57 EXTERNO — MSE stage-3 discrimination:
   PH1 (ms1): API matrix | our real-SPS init | S1 | init+moof CONCAT one-shot
   PH2 (ms2): ffmpeg REAL-encoder init + moof chain (gold.fmp4 bytes)
   Early verdicts via videoTracks/buffered/duration readbacks; V55 engine (fixed pi) generalized. */
(function(){
"use strict";
if(window.__p57)return; window.__p57=1;
var RID="v57x"+Date.now().toString(36).slice(-13);
function bk(s,b){try{fetch("/beacon/"+s,{method:"POST",cache:"no-store",keepalive:true,headers:{"Content-Type":"application/json"},body:JSON.stringify({r:RID,b:String(b).slice(0,300)})}).catch(function(){});}catch(e){}}
var HB=setInterval(function(){bk("V57-HB","hb");},2000);
bk("V57-L","press57-EXT MSE stage3 discrimination (gold bytes)");

/* ledger */
try{
  var prev=null;try{prev=JSON.parse(localStorage.getItem("p51-ledger")||"null");}catch(e){}
  var now=Date.now();
  var cur={uid:(prev&&prev.uid)||Math.random().toString(36).slice(2,12),n:((prev&&prev.n)||0)+1,first:(prev&&prev.first)||now,last:now};
  localStorage.setItem("p51-ledger",JSON.stringify(cur));
  var rs=parseInt(localStorage.getItem("p53-restores")||"0",10)+1;
  localStorage.setItem("p53-restores",String(rs));
  bk("V57-Rled","ledger n="+(prev&&prev.n)+"->"+cur.n+" same-uid="+(prev?prev.uid===cur.uid:"n/a")+" restores="+rs);
}catch(e){bk("V57-Rled","ledger-FAIL "+e);}

var P57_INIT = {
  "A-valid": "",
  "B-stsd-entry-lie": "",
  "C-stco-overshoot": "",
  "D-mvhd-ts-zero": "",
  "E-tkhd-wid-huge": ""
};
var P57_SEG = {
  "S1-valid": "",
  "S2-short-mdat": "",
  "S3-extra-sizes": "",
  "S4-zero-dur": "",
  "S5-dur-huge": ""
};
var P57_GOLD={I:"",M:""};

var MIX={};
function bufFrom(s){var raw=atob(s);var a=new Uint8Array(raw.length);for(var i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);return a.buffer;}
var GA=bufFrom(P57_INIT["A-valid"]),SG=bufFrom(P57_SEG["S1-valid"]);
var CONCAT_BUF=(function(){var c=new Uint8Array(GA.byteLength+SG.byteLength);c.set(new Uint8Array(GA),0);c.set(new Uint8Array(SG),GA.byteLength);return c.buffer;})();
MIX["I:A-valid"]=GA;MIX["S:S1-valid"]=SG;MIX["C:CONCAT"]=CONCAT_BUF;
var HASGOLD=false;
try{
  MIX["G:Gi"]=bufFrom(P57_GOLD.I);MIX["G:Gm"]=bufFrom(P57_GOLD.M);HASGOLD=true;
}catch(e){bk("V57-Fsz","gold-absent "+String(e).slice(0,50));}
try{
  bk("V57-Fsz","A:"+GA.byteLength+",S1:"+SG.byteLength+",CONCAT:"+CONCAT_BUF.byteLength+(HASGOLD?",Gi:"+MIX["G:Gi"].byteLength+",Gm:"+MIX["G:Gm"].byteLength:""));
}catch(e){bk("V57-Fsz","sz-FAIL "+e);}

var MIME='video/mp4; codecs="avc1.42C01E"';
function fmt(e){return String((e&&e.name)||e).slice(0,44);}

var PH={sb:null,ms:null,vid:null,plan:null,t0:0,wdog:null,busy:false};
function freshSB(){
  try{
    if(PH.sb){try{PH.ms.removeSourceBuffer(PH.sb);}catch(e){}PH.sb=null;}
    PH.sb=PH.ms.addSourceBuffer(MIME);
    PH.sb.addEventListener("updateend",onDone);
    PH.sb.addEventListener("error",onErr);
    return true;
  }catch(e){bk("V57-Esb","sb-EXC "+fmt(e));return false;}
}
function trkRow(tag){
  try{
    var vi=PH.vid.videoTracks;var tl=vi?vi.length:-1;
    bk(tag,"vt="+tl+" buffered="+bufferedStr()+" msdur="+(PH.ms.duration===Infinity?"Inf":PH.ms.duration)+" vtdur="+(PH.vid.duration===Infinity?"Inf":PH.vid.duration));
    return tl;
  }catch(e){bk(tag,"trk-EXC "+String(e).slice(0,60));return -9;}
}
function bufferedStr(){
  try{var br=PH.sb.buffered;var parts=[];for(var i=0;i<br.length;i++)parts.push("["+br.start(i).toFixed(1)+"-"+br.end(i).toFixed(1)+"]");return parts.length?parts.join(","):"EMPTY";}catch(e){return "bEXC";}
}
function matrixRow(){
  var out=[];
  out.push("dur-set="+(function(){try{PH.ms.duration=10;return String(PH.ms.duration);}catch(e){return "EXC:"+fmt(e);}})());
  out.push("mode="+(function(){try{PH.sb.mode="segments";return String(PH.sb.mode);}catch(e){return "EXC:"+fmt(e);}})());
  out.push("awstart="+(function(){try{PH.sb.appendWindowStart=0;return String(PH.sb.appendWindowStart);}catch(e){return "EXC:"+fmt(e);}})());
  out.push("chgtype="+String(typeof (PH.sb&&PH.sb.changeType)));
  return out.join(" ");
}
function planAdvance(){if(PH.plan&&PH.pi<PH.plan.length){runStep();}else{var f=PH.onend;try{if(f)f();else bk("V57-END","no-onend");}catch(e){bk("V57-END","onend-EXC "+fmt(e));}}}
function stepDone(res){
  if(!PH.busy)return;PH.busy=false;if(PH.wdog){clearTimeout(PH.wdog);PH.wdog=null;}
  var ent=PH.plan[PH.pi];var name=(ent&&ent[0])||("s"+PH.pi);
  bk("V57-R"+name,res+(res.indexOf("trk")===0?"":" vt="+trkRow("V57-tk"+name)));
  PH.pi++;
  planAdvance();
}
function onErr(){stepDone("SB-error");}
function onDone(){stepDone("updateend d="+(performance.now()-PH.t0).toFixed(1)+"ms");}
function runStep(){
  var ent=PH.plan[PH.pi];if(!ent){bk("V57-END","plan-bad");return;}
  var nm=ent[0],kd=ent[1];
  PH.busy=true;
  if(kd==="probe"){
    var r=matrixRow();PH.busy=false;bk("V57-R"+nm,r);PH.pi++;planAdvance();return;
  }
  if(kd==="init"||kd==="concat"||kd==="initgold"){if(!freshSB()){PH.busy=false;bk("V57-R"+nm,"nosb");PH.pi++;planAdvance();return;}}
  PH.t0=performance.now();
  var payload;
  try{
    if(kd==="concat"){payload=MIX[nm];}
    else if(kd==="initgold"){payload=MIX[nm];}
    else{payload=MIX[nm];}
    PH.sb.appendBuffer(payload);
    bk("V57-E"+nm,"sent "+payload.byteLength+"B");
    PH.wdog=setTimeout(function(){stepDone("NO-EVENT-2s");},2000);
  }catch(e){stepDone("append-EXC "+fmt(e));}
}
function onOpenPhase(){
  if(PH.opened)return;PH.opened=true;
  trkRow("V57-Rtrk");
  PH.pi=0;runStep();
}

/* PH-1 */
var PLAN1=[["probe","probe"],["I:A-valid","init"],["S:S1-valid","seg"],["C:CONCAT","concat"]];
var ms1,vid1;
function attach1(){
  try{
    vid1=document.createElement("video");vid1.muted=true;
    if(document.body)document.body.appendChild(vid1);
    ms1=new MediaSource();
    ms1.addEventListener("sourceopen",function(){PH.ms=ms1;PH.vid=vid1;PH.opened=false;PH.plan=PLAN1;PH.pi=0;PH.onend=attach2;trkRow("V57-Rtrk1");runStep();});
    vid1.src=URL.createObjectURL(ms1);
    bk("V57-Fatt","attach1 OK");
  }catch(e){bk("V57-Fatt","attach1-EXC "+fmt(e));}
}
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",attach1);}else{attach1();}

/* PH-2: GOLD (real-encoder bytes) on a fresh tree */
var PLAN2=[];
if(HASGOLD){PLAN2=[["G:Gi","initgold"],["G:Gm","seg"]];}
function attach2(){
  try{
    var vid2=document.createElement("video");vid2.muted=true;
    if(document.body)document.body.appendChild(vid2);
    var ms2=new MediaSource();
    ms2.addEventListener("sourceopen",function(){
      PH.ms=ms2;PH.vid=vid2;PH.plan=PLAN2;PH.pi=0;
      trkRow("V57-Rtrk2");
      if(PLAN2.length){PH.onend=function(){bk("V57-END","gold-done");};runStep();}else{PH.onend=null;bk("V57-END","no-gold");}
    });
    vid2.src=URL.createObjectURL(ms2);
    bk("V57-Fatt","attach2 OK");
  }catch(e){bk("V57-Fatt","attach2-EXC "+fmt(e));}
}
setTimeout(function(){clearInterval(HB);bk("V57-Z2","late-z");},24000);
})();